function validate([nums]) {
  const n = nums.length;
  if (n < 4 || n > 4000) return 'nums needs 4 to 4000 values.';
  const seen = new Array(n + 1).fill(false);
  for (const v of nums) {
    if (!Number.isInteger(v) || v < 1 || v > n) return 'Each value must be an integer from 1 to nums.length.';
    if (seen[v]) return 'Values must be distinct (nums is a permutation).';
    seen[v] = true;
  }
  return null;
}

