function countQuadruplets(nums) {
  const n = nums.length;
  const triples = new Array(n).fill(0);
  let count = 0;

  for (let k = 0; k < n; k++) {
    let smaller = 0;
    for (let j = 0; j < k; j++) {
      if (nums[j] < nums[k]) {
        count += triples[j];
        smaller++;
      } else {
        triples[j] += smaller;
      }
    }
  }
  return count;
}

