function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 4 + Math.floor(rand() * 9);
  const nums = Array.from({ length: n }, (_, i) => i + 1);
  const shape = rand();
  if (shape < 0.6) {
    // A uniformly random permutation.
    for (let i = n - 1; i > 0; i--) {
      const r = Math.floor(rand() * (i + 1));
      [nums[i], nums[r]] = [nums[r], nums[i]];
    }
  } else if (shape < 0.8) {
    // Swap neighbouring pairs: 2,1,4,3,... makes many quadruplets.
    for (let i = 0; i + 1 < n; i += 2) if (rand() < 0.9) [nums[i], nums[i + 1]] = [nums[i + 1], nums[i]];
  } else {
    // Mostly sorted, with a few random swaps.
    const swaps = 1 + Math.floor(rand() * Math.max(1, n / 4));
    for (let s = 0; s < swaps; s++) {
      const x = Math.floor(rand() * n), y = Math.floor(rand() * n);
      [nums[x], nums[y]] = [nums[y], nums[x]];
    }
  }
  return [nums];
}
